import logging
from functools import wraps
import uuid
import os
from importlib.metadata import version, PackageNotFoundError
from taf.internal.impact_radar import log_radar

from taf.gnb.oam.coam.vdu.utilities.urllib3_retry_filter import Urllib3RetryFilter

logging.captureWarnings(True)
logger = logging.getLogger("taf.gnb.oam.coam.vdu")
logger.addHandler(logging.NullHandler())

urllib3_logger = logging.getLogger('urllib3.connectionpool')
urllib3_logger.addFilter(Urllib3RetryFilter())


def log_debug(message):
    """
    Log a debug level message
    """
    logger.debug(message)


def log_warning(message):
    """
    Log a warning level message.
    """
    logger.warning(message)


def log_error(message):
    """
    Log an error level message
    """
    logger.error(message)


def log_library_version():
    """
    Log version of taf.gnb.oam.coam.vdu for the debug purposes.
    """
    try:
        library_version = version('taf.gnb.oam.coam.vdu')
    except PackageNotFoundError:
        library_version = 'not found'

    log_debug(f"Installed taf.gnb.oam.coam.vdu library version: {library_version}")


def direct_logs_to_file(alias, path=""):
    """
    Direct logs to file in the location given by path on condition that logging was not disabled by
    setting env variable TAF_VDU_CLIENT_DISABLE_LOGGING to True.

    If path is not given, file with logs will be saved to the current directory.
    If directory given by path does not exist it will be created.
    If directory creation failed warning message will be logged and logs will not be directed to a file.
    """
    if os.getenv("TAF_VDU_CLIENT_DISABLE_LOGGING", "False").lower() != "true":
        log_dir = os.path.join(path, f"vdu_api_debug_{alias}.log")

        if path and not os.path.isdir(path):
            try:
                os.makedirs(path)
            except (FileExistsError, OSError):
                log_warning(f"Failed to create directory {path}. "
                            f"Log messages will not be directed to a file, please provide valid log_dir")
                return

        file_handler = logging.FileHandler(log_dir)
        file_handler.setLevel(logging.DEBUG)

        formatter = logging.Formatter('%(asctime)s %(levelname)s %(name)s - %(message)s')
        file_handler.setFormatter(formatter)

        logger.addHandler(file_handler)


def set_log_level(level):
    """
    Sets the lowest-severity of log messages which should be logged to console.
    If given level is invalid, INFO level will be set.
    """
    levels = {
        "debug": logging.DEBUG,
        "info": logging.INFO,
        "warning": logging.WARNING,
        "error": logging.ERROR,
        "critical": logging.CRITICAL
    }

    if level.lower() not in levels:
        log_warning(f"Invalid log_level: {level}. Setting log level to INFO")
        level = "info"

    stream_handler = logging.StreamHandler()
    stream_handler.setLevel(levels[level.lower()])

    stream_formatter = logging.Formatter('%(levelname)s:%(name)s:%(message)s')
    stream_handler.setFormatter(stream_formatter)

    logger.addHandler(stream_handler)


def log_sending_message(request_id, endpoint, headers, method, connection_alias, payload=None, json=None, log_payload=True):
    extra = {
                "http_request": {
                    "request_id": request_id,
                    "method": method,
                    "url": endpoint,
                    "query_params": payload if log_payload else None,
                    "headers": headers,
                    "json": json,
                    "connection_alias": connection_alias
                }
    }

    logger.debug(f"Sending message: {extra}", extra=extra)

    log_radar(
        message="Sending VDU request",
        request_url=endpoint,
        request_method=method,
        request_params=payload,
        request_json=json,
    )


def log_received_response(request_id, response, endpoint, method, connection_alias):
    response_content = ' '.join(response.content.decode('utf-8', 'ignore').split())
    if len(response_content) > 1000:
        response_content = response_content[:1000] + '...'

    msg = {
                "http_response": {
                    "request_id": request_id,
                    "method": method,
                    "url": endpoint,
                    "status_code": response.status_code,
                    "reason": response.reason,
                    "connection_alias": connection_alias
                }
    }

    extra = msg.copy()

    try:
        if (response.headers['Content-Type'] == 'application/json') and (len(response.content) > 0):
            extra["http_response"]["body"] =  response.json()
        else:
            extra["http_response"]["body"] = response.content

    except KeyError:
        extra["http_response"]["body"] = response.content

    msg["http_response"]["body"] = response_content

    logger.debug(f"Received response: {msg}", extra=extra)


def log_request_response(func):     # noqa: C901
    #TODO: Functionality will be removed after transition to internal HTTP client
    @wraps(func)
    def wrapper(*args, **kwargs):
        disable_log = os.getenv("TAF_VDU_CLIENT_DISABLE_LOGGING", "False").lower() == "true"
        try:
            request_id = uuid.uuid4()
            result = func(*args, **kwargs)
            if not disable_log:
                logger.debug(f"Send message: request_id={request_id} {args[0]} {args[1]} {kwargs}")
                response = ' '.join(result.data.decode('utf-8', 'ignore').split())
                if len(response) > 1000:
                    response = response[:1000] + '...'

                logger.debug(f"Received response: request_id={request_id} {args[0]} {args[1]} {result.status} {response}")

            return result
        except Exception as api_err:
            if not disable_log:
                if 'ApiException' in type(api_err).__name__:
                    logger.debug(f"Send message: request_id={request_id} {args[0]} {args[1]} {kwargs}")
                    logger.debug(f"Received response: request_id={request_id} {args[0]} {args[1]} {api_err.status} "
                                 f"{api_err.reason} {api_err.body.decode('utf-8', 'ignore')}")
            raise api_err

    return wrapper
